-- GATE PACK 0255 exec (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select p.proname as obj, pg_catalog.oidvectortypes(p.proargtypes) as args, p.prosecdef as definer,
  coalesce((select substr(c, 13) from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%'), '') as search_path,
  coalesce((select string_agg(r, ',' order by r) from (values ('anon'), ('authenticated')) as x(r)
            where has_function_privilege(x.r, p.oid, 'EXECUTE')), '') as exec_roles,
  exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE') as exec_public
from pg_catalog.pg_proc p
where p.oid in (pg_catalog.to_regprocedure('public.snapshot_appointment_buffer()'), pg_catalog.to_regprocedure('public.handle_new_user()'), pg_catalog.to_regprocedure('public.enforce_appointment_buffer()'), pg_catalog.to_regprocedure('public.guard_scoped_recurring_rule_capacity()'), pg_catalog.to_regprocedure('public.studios_admission_mode_guard()'), pg_catalog.to_regprocedure('public.is_studio_member(uuid)'), pg_catalog.to_regprocedure('public.is_studio_owner(uuid)'), pg_catalog.to_regprocedure('public.session_is_visible(uuid)'))
order by 1, 2;
